using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

public class FishSceneDump
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();

        for (int s = 0; s < SceneManager.sceneCount; s++)
        {
            Scene scene = SceneManager.GetSceneAt(s);
            if (!scene.isLoaded) continue;
            sb.AppendLine("== SCENE " + scene.name + " ==");
            GameObject[] roots = scene.GetRootGameObjects();
            for (int i = 0; i < roots.Length; i++) walk(roots[i].transform, 0, sb);
        }

        Debug.Log("[FishSceneDump]\n" + sb);
    }

    private static void walk(Transform t, int depth, StringBuilder sb)
    {
        string indent = new string(' ', depth * 2);
        Vector3 lp = t.localPosition;
        Vector3 wp = t.position;
        Vector3 ls = t.localScale;
        string typeList = "";
        Component[] cs = t.GetComponents<Component>();
        for (int i = 0; i < cs.Length; i++)
        {
            if (cs[i] == null) { typeList += " <MISSING>"; continue; }
            if (cs[i] is Transform) continue;
            typeList += cs[i].GetType().Name + " ";
        }
        sb.AppendLine(indent + t.name + " | pos(" + Fmt(lp.x) + "," + Fmt(lp.y) + "," + Fmt(lp.z) + ") world(" + Fmt(wp.x) + "," + Fmt(wp.y) + "," + Fmt(wp.z) + ") scale(" + Fmt(ls.x) + "," + Fmt(ls.y) + "," + Fmt(ls.z) + ") | " + typeList);
        for (int i = 0; i < t.childCount; i++) walk(t.GetChild(i), depth + 1, sb);
    }

    private static string Fmt(float v)
    {
        return v.ToString("0.00");
    }
}
